public class Solution {

    public static List<List<Integer>> solve(List<Integer> testTup, int n) {
        List<List<Integer>> result = new ArrayList<>();
        if (testTup.size() == 0) {
            return result;
        }
        int i = 0;
        while (i < testTup.size()) {
            List<Integer> temp = new ArrayList<>();
            for (int j = i; j < i + n; j++) {
                if (j < testTup.size()) {
                    temp.add(testTup.get(j));
                }
            }
            result.add(temp);
            i += n;
        }
        return result;
    }
}

