public class Solution {

    public static Boolean solve(int[] a, int[] b, int n, int m) {
        if (n < m) {
            return false;
        }

        int i = 0;

        while (i <= n - m) {
            int j;
            for (j = 0; j < m; j++) {
                if (a[i + j] != b[j]) {
                    break;
                }
            }

            if (j == m) {
                return true;
            }

            i++;
        }

        return false;
    }
}

