public class Solution {

    public static int solve(int n) {
        int lastDigit = 0;
        int factorial = 1;
        for (int i = n; i >= 1; i--) {
            factorial = factorial * i;
        }
        int lastDigitInFactorial = (int) Math.log10(factorial);
        if (lastDigitInFactorial > 0) {
            lastDigit = n % 10;
        }
        return lastDigit;
    }
}

